config.renderFunction:
function render(ctx, width, height, state) {
  const p = state.power;

  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(0, 0, width, height);

  const ox = 60;
  const oy = height - 50;
  const scaleX = (width - 100) / 4;
  const scaleY = (height - 90) / 4;

  ctx.strokeStyle = '#334155';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = 0; x <= 4; x++) {
    const px = ox + x * scaleX;
    ctx.moveTo(px, 30);
    ctx.lineTo(px, oy);
  }
  for (let y = 0; y <= 4; y++) {
    const py = oy - y * scaleY;
    ctx.moveTo(ox, py);
    ctx.lineTo(width - 40, py);
  }
  ctx.stroke();

  ctx.strokeStyle = '#64748b';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(ox, 20);
  ctx.lineTo(ox, oy + 10);
  ctx.moveTo(ox - 10, oy);
  ctx.lineTo(width - 20, oy);
  ctx.stroke();

  ctx.fillStyle = '#94a3b8';
  ctx.font = '12px sans-serif';
  for (let x = 1; x <= 4; x++) {
    ctx.fillText(x.toString(), ox + x * scaleX - 4, oy + 18);
  }
  for (let y = 1; y <= 4; y++) {
    ctx.fillText(y.toString(), ox - 18, oy - y * scaleY + 4);
  }

  ctx.beginPath();
  ctx.strokeStyle = '#38bdf8';
  ctx.lineWidth = 3;

  let first = true;
  for (let px = 0; px <= width - 100; px += 2) {
    const x = px / scaleX;
    const y = Math.pow(x, p);
    const py = oy - y * scaleY;
    if (py < 20) break;
    if (first) {
      ctx.moveTo(ox + px, py);
      first = false;
    } else {
      ctx.lineTo(ox + px, py);
    }
  }
  ctx.stroke();

  const crossX = ox + 1 * scaleX;
  const crossY = oy - 1 * scaleY;
  ctx.fillStyle = '#f43f5e';
  ctx.beginPath();
  ctx.arc(crossX, crossY, 5, 0, Math.PI * 2);
  ctx.fill();

  ctx.font = 'bold 14px monospace';
  ctx.fillStyle = '#38bdf8';
  const label = p === 0.5 ? 'y = √x (p = 0.5)' : (p === 0.33 ? 'y = ∛x' : 'y = x^(' + p.toFixed(2) + ')');
  ctx.fillText(label, ox + 20, 45);

  ctx.font = '12px sans-serif';
  ctx.fillStyle = '#e2e8f0';
  ctx.fillText('Crossover Invariance Point (1, 1)', crossX + 10, crossY - 8);

  ctx.fillStyle = '#94a3b8';
  ctx.fillText(p < 1 ? 'Sub-linear: Decreasing rate of growth (Concave Down)' : (p > 1 ? 'Super-linear: Accelerating growth (Concave Up)' : 'Linear: Constant slope m = 1'), ox + 20, 68);
}
